SELECT TABLE_NAME, INDEX_NAME, NON_UNIQUE, GROUP_CONCAT(COLUMN_NAME ORDER BY SEQ_IN_INDEX) COLUNAS FROM information_schema.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME IN ('CANAIS','VIDEOS','TRECHOS','TEMAS','VIDEO_TEMAS','PLAYLISTS','PLAYLIST_VIDEOS','AVISOS','CONFIG','PRATICAS','MENTOR_REGRAS','LOTES','LIVRO_CAPITULOS') GROUP BY TABLE_NAME, INDEX_NAME, NON_UNIQUE ORDER BY TABLE_NAME, INDEX_NAME